"use client";
import { createContext, useCallback, useContext, useEffect, useMemo, useRef, useState, type CSSProperties, type Dispatch, type ReactNode, type SetStateAction } from "react";
import { appearanceStorageKey, presetsStorageKey, defaultAppearance, createAppearance, normalizeAppearance, parseAppearance, resolveAppearance, type AppearanceConfig, type SavedAppearance } from "@/lib/appearance";
import "@/styles/effects.css";

interface AppearanceContextValue {
  appearance: AppearanceConfig;
  setAppearance: Dispatch<SetStateAction<AppearanceConfig>>;
  resetAppearance: () => void;
  presets: SavedAppearance[];
  savePreset: (name: string) => void;
  deletePreset: (id: string) => void;
  applyPreset: (id: string) => void;
  importAppearance: (text: string) => void;
}
const noop = () => {};
const Context = createContext<AppearanceContextValue>({ appearance: defaultAppearance, setAppearance: noop, resetAppearance: noop, presets: [], savePreset: noop, deletePreset: noop, applyPreset: noop, importAppearance: noop });
export function useAppearance() { return useContext(Context); }

export function applyAppearanceToDocument(config: AppearanceConfig) {
  const root = document.documentElement;
  root.classList.toggle("dark", config.theme === "dark");
  root.style.colorScheme = config.theme;
  root.dataset.palette = config.palette;
  root.dataset.material = config.material;
  root.dataset.motionLevel = config.motion;
  root.dataset.hoverEffect = config.hover;
  root.dataset.density = config.density;
  root.dataset.typography = config.typography;
  for (const [name, value] of Object.entries(resolveAppearance(config))) root.style.setProperty(name, value);
  window.dispatchEvent(new CustomEvent("aureform:appearance-change", { detail: config }));
}
function loadAppearance(): AppearanceConfig {
  try {
    const raw = localStorage.getItem(appearanceStorageKey);
    if (raw) return parseAppearance(raw);
    const legacy = localStorage.getItem("aureform:theme");
    return createAppearance("aurora", legacy === "light" ? "light" : "dark");
  } catch { return createAppearance(); }
}
function loadPresets(): SavedAppearance[] {
  try {
    const input: unknown = JSON.parse(localStorage.getItem(presetsStorageKey) || "[]");
    if (!Array.isArray(input)) return [];
    return input.slice(0, 100).flatMap((item) => {
      try {
        if (typeof item?.id !== "string" || typeof item?.name !== "string") return [];
        return [{ id: item.id.slice(0, 80), name: item.name.slice(0, 80), config: normalizeAppearance(item.config) }];
      } catch { return []; }
    });
  } catch { return []; }
}
export function AppearanceProvider({ children, initialAppearance = defaultAppearance, applyToDocument = true }: {
  children: ReactNode; initialAppearance?: AppearanceConfig; applyToDocument?: boolean;
}) {
  const [appearance, setState] = useState<AppearanceConfig>(initialAppearance);
  const [initialProps, setInitialProps] = useState({ initialAppearance, applyToDocument });
  const [presets, setPresets] = useState<SavedAppearance[]>([]);
  const appearanceRef = useRef(initialAppearance);
  const presetsRef = useRef<SavedAppearance[]>([]);
  // A controlled scope must expose new props before its children commit.
  // Adjusting this provider's state during its own render avoids a second,
  // passive state update for every color or range input in the Studio.
  if (initialProps.initialAppearance !== initialAppearance || initialProps.applyToDocument !== applyToDocument) {
    setInitialProps({ initialAppearance, applyToDocument });
    if (!applyToDocument) setState(initialAppearance);
  }
  useEffect(() => {
    if (!applyToDocument) return;
    const hydrate = () => {
      const next = loadAppearance();
      appearanceRef.current = next;
      setState(next);
      const saved = loadPresets();
      presetsRef.current = saved;
      setPresets(saved);
      applyAppearanceToDocument(next);
    };
    hydrate();
    const onStorage = (event: StorageEvent) => {
      if (event.key === appearanceStorageKey || event.key === presetsStorageKey || event.key === "aureform:theme") hydrate();
    };
    window.addEventListener("storage", onStorage);
    return () => window.removeEventListener("storage", onStorage);
  }, [applyToDocument]);
  useEffect(() => {
    if (!applyToDocument) {
      appearanceRef.current = initialAppearance;
    }
  }, [initialAppearance, applyToDocument]);
  const setAppearance = useCallback<Dispatch<SetStateAction<AppearanceConfig>>>((update) => {
    const next = normalizeAppearance(typeof update === "function" ? update(appearanceRef.current) : update);
    appearanceRef.current = next;
    setState(next);
    if (applyToDocument) {
      applyAppearanceToDocument(next);
      try {
        const serialized = JSON.stringify(next);
        localStorage.setItem(appearanceStorageKey, serialized);
        localStorage.setItem("aureform:appearance-paint:v1", JSON.stringify({ config: serialized, variables: resolveAppearance(next) }));
        localStorage.setItem("aureform:theme", next.theme);
      } catch { /* A blocked storage leaves the current appearance usable. */ }
    }
  }, [applyToDocument]);
  const updatePresets = useCallback((update: (previous: SavedAppearance[]) => SavedAppearance[]) => {
    const next = update(presetsRef.current);
    presetsRef.current = next;
    setPresets(next);
    if (applyToDocument) { try { localStorage.setItem(presetsStorageKey, JSON.stringify(next)); } catch {} }
  }, [applyToDocument]);
  const resetAppearance = useCallback(() => setAppearance(createAppearance()), [setAppearance]);
  const savePreset = useCallback((name: string) => {
    const label = name.trim().slice(0, 80);
    if (!label) throw new Error("Give your preset a name.");
    updatePresets((previous) => [...previous.slice(-99), { id: crypto.randomUUID(), name: label, config: normalizeAppearance(appearance) }]);
  }, [appearance, updatePresets]);
  const deletePreset = useCallback((id: string) => updatePresets((previous) => previous.filter((p) => p.id !== id)), [updatePresets]);
  const applyPreset = useCallback((id: string) => { const preset = presets.find((p) => p.id === id); if (preset) setAppearance(preset.config); }, [presets, setAppearance]);
  const importAppearance = useCallback((text: string) => setAppearance(parseAppearance(text)), [setAppearance]);
  const value = useMemo(() => ({ appearance, setAppearance, resetAppearance, presets, savePreset, deletePreset, applyPreset, importAppearance }), [appearance, setAppearance, resetAppearance, presets, savePreset, deletePreset, applyPreset, importAppearance]);
  return <Context.Provider value={value}>{children}</Context.Provider>;
}
export function AppearanceScope({ appearance, children, className = "" }: { appearance: AppearanceConfig; children: ReactNode; className?: string }) {
  const normalized = useMemo(() => normalizeAppearance(appearance), [appearance]);
  return (
    <AppearanceProvider initialAppearance={normalized} applyToDocument={false}>
      <div className={`af-appearance-scope ${normalized.theme === "dark" ? "dark" : ""} ${className}`}
        data-palette={normalized.palette} data-material={normalized.material} data-motion-level={normalized.motion}
        data-hover-effect={normalized.hover} data-density={normalized.density} data-typography={normalized.typography}
        style={{ ...resolveAppearance(normalized), colorScheme: normalized.theme } as CSSProperties}>
        {children}
      </div>
    </AppearanceProvider>
  );
}

"use client";
import { useEffect, useRef, useState } from "react";
import type { Map as MapInstance } from "maplibre-gl";
import "maplibre-gl/dist/maplibre-gl.css";
import {
  land,
  routeGeometry,
  gridGeometry,
  shipmentRoutes,
} from "@/demo/map-data";
import { useTheme } from "@/components/providers";
import { useAppearance } from "@/components/appearance-provider";
import { useLanguage } from "@/hooks/use-language";
export function RouteMap({
  selected = "all",
  label,
}: {
  selected?: string;
  label: string;
}) {
  const container = useRef<HTMLDivElement>(null),
    map = useRef<MapInstance | null>(null),
    [fallback, setFallback] = useState(false),
    { theme } = useTheme(),
    { appearance } = useAppearance(),
    { locale, l } = useLanguage();
  useEffect(() => {
    let disposed = false;
    void import("maplibre-gl")
      .then((lib) => {
        if (disposed || !container.current) return;
        try {
          const styles = getComputedStyle(document.documentElement),
            color = (name: string) => styles.getPropertyValue(name).trim();
          const instance = new lib.Map({
            container: container.current,
            center: [-32, 27],
            zoom: 1.4,
            minZoom: 0.4,
            maxZoom: 9,
            renderWorldCopies: false,
            attributionControl: false,
            scrollZoom: false,
            locale: {
              "NavigationControl.ZoomIn": l("Zoom in", "Acercar"),
              "NavigationControl.ZoomOut": l("Zoom out", "Alejar"),
              "NavigationControl.ResetBearing": l(
                "Reset bearing",
                "Restablecer orientación",
              ),
            },
            style: {
              version: 8,
              sources: {
                land: { type: "geojson", data: land },
                grid: { type: "geojson", data: gridGeometry },
                routes: { type: "geojson", data: routeGeometry },
              },
              layers: [
                {
                  id: "water",
                  type: "background",
                  paint: { "background-color": color("--surface-subtle") },
                },
                {
                  id: "grid",
                  type: "line",
                  source: "grid",
                  paint: { "line-color": color("--border"), "line-width": 0.5 },
                },
                {
                  id: "land",
                  type: "fill",
                  source: "land",
                  paint: {
                    "fill-color": color("--accent"),
                    "fill-outline-color": color("--border"),
                  },
                },
                {
                  id: "routes",
                  type: "line",
                  source: "routes",
                  paint: {
                    "line-color": color("--primary"),
                    "line-width": 2,
                    "line-dasharray": [2, 2],
                  },
                },
              ],
            },
          });
          map.current = instance;
          instance.addControl(
            new lib.NavigationControl({ showCompass: false }),
            "top-right",
          );
          instance.getCanvas().setAttribute("aria-label", label);
          instance.on("load", () => {
            if (disposed) return;
            for (const route of shipmentRoutes) {
              for (const [name, position] of [
                [route.from, route.start],
                [route.to, route.end],
              ] as const) {
                const button = document.createElement("button");
                button.type = "button";
                button.setAttribute("aria-label", `${route.id}: ${name}`);
                button.className =
                  "flex size-4 items-center justify-center rounded-full border-[3px] border-surface bg-primary shadow-sm";
                const text = document.createElement("p");
                text.textContent = `${route.id} · ${name}`;
                text.style.cssText =
                  "color:#222c26;font-size:11px;padding:4px;font-family:Manrope,sans-serif";
                new lib.Marker({ element: button })
                  .setLngLat(position)
                  .setPopup(new lib.Popup({ offset: 10 }).setDOMContent(text))
                  .addTo(instance);
              }
            }
          });
          instance.on("error", () => {
            if (!disposed && !instance.loaded()) setFallback(true);
          });
        } catch {
          if (!disposed) setFallback(true);
        }
      })
      .catch(() => {
        if (!disposed) setFallback(true);
      });
    return () => {
      disposed = true;
      map.current?.remove();
      map.current = null;
    };
  }, [label, l, locale]);
  useEffect(() => {
    const instance = map.current;
    if (!instance) return;
    const update = () => {
      const styles = getComputedStyle(document.documentElement);
      for (const [id, property, token] of [
        ["water", "background-color", "--surface-subtle"],
        ["grid", "line-color", "--border"],
        ["land", "fill-color", "--accent"],
        ["routes", "line-color", "--primary"],
      ])
        instance.setPaintProperty(
          id,
          property,
          styles.getPropertyValue(token).trim(),
        );
    };
    if (instance.isStyleLoaded()) update();
    else instance.once("load", update);
  }, [theme, appearance.colors, appearance.palette]);
  useEffect(() => {
    const instance = map.current;
    if (!instance) return;
    const route = shipmentRoutes.find((item) => item.id === selected);
    if (route)
      instance.fitBounds([route.start, route.end], {
        padding: 65,
        maxZoom: 6,
        duration: window.matchMedia("(prefers-reduced-motion: reduce)").matches
          ? 0
          : 500,
      });
    else instance.flyTo({ center: [-32, 27], zoom: 1.4, duration: 0 });
  }, [selected]);
  return (
    <div className="relative h-[460px] overflow-hidden rounded-xl border border-border">
      <div
        ref={container}
        className="h-full w-full"
        role="region"
        aria-label={label}
      />
      {fallback && (
        <div className="absolute inset-0 bg-surface-subtle">
          <SchematicMap selected={selected} label={label} />
          <span className="absolute bottom-3 left-3 rounded bg-surface/90 px-3 py-1.5 text-[9px]">
            {l(
              "Schematic view · WebGL unavailable",
              "Vista esquemática · WebGL no disponible",
            )}
          </span>
        </div>
      )}
      <span className="pointer-events-none absolute bottom-3 right-3 rounded bg-surface/90 px-3 py-1.5 text-[9px] text-muted-foreground">
        {l(
          "Original schematic geometry · Demo",
          "Geometría esquemática original · Demo",
        )}
      </span>
    </div>
  );
}
function SchematicMap({
  selected,
  label,
}: {
  selected: string;
  label: string;
}) {
  const x = (longitude: number) => (longitude + 180) * 2,
    y = (latitude: number) => (90 - latitude) * 2;
  return (
    <svg
      viewBox="0 0 720 360"
      role="img"
      aria-label={label}
      className="h-full w-full"
    >
      {land.features.map((feature, i) => (
        <path
          key={i}
          d={feature.geometry.coordinates
            .map(
              (ring) =>
                ring
                  .map(
                    (point, j) =>
                      `${j ? "L" : "M"}${x(point[0])},${y(point[1])}`,
                  )
                  .join(" ") + "Z",
            )
            .join(" ")}
          fill="var(--accent)"
          stroke="var(--border)"
        />
      ))}
      {shipmentRoutes
        .filter((route) => selected === "all" || route.id === selected)
        .map((route) => (
          <g key={route.id}>
            <line
              x1={x(route.start[0])}
              y1={y(route.start[1])}
              x2={x(route.end[0])}
              y2={y(route.end[1])}
              stroke="var(--primary)"
              strokeWidth={2}
            />
            <circle
              cx={x(route.start[0])}
              cy={y(route.start[1])}
              r={4}
              fill="var(--primary)"
            />
            <text
              x={x(route.start[0]) + 8}
              y={y(route.start[1]) - 8}
              fontSize={10}
              fill="var(--foreground)"
            >
              {route.id}
            </text>
          </g>
        ))}
    </svg>
  );
}

"use client";

import {
  createContext,
  useCallback,
  useContext,
  useEffect,
  useLayoutEffect,
  useMemo,
  useRef,
  useState,
  type ReactNode,
} from "react";
import { useWorkspace } from "@/components/workspace-provider";
import { createCommerceSeed } from "@/demo/commerce-data";
import {
  CommerceError,
  buildOrder,
  commerceInvoiceSchema,
  commerceOrderSchema,
  commerceProductSchema,
  newInvoiceSchema,
  type CommerceAction,
  type CommerceAdapter,
  type CommerceContextValue,
  type CommerceScope,
  type CommerceSnapshot,
} from "@/lib/commerce";
import {
  COMMERCE_STORAGE_PREFIX,
  commercePlans,
  completeMockCheckout,
  parseCommerceSnapshot,
  upsertCommerceProduct,
} from "@/lib/commerce-state";
import { parseStripeAction } from "@/lib/stripe-commerce-adapter";

const Context = createContext<CommerceContextValue | null>(null);
type Session = {
  workspaceId: string;
  snapshot: CommerceSnapshot;
  ready: boolean;
};
const now = () => new Date().toISOString();
const identifier = (prefix: string) => `${prefix}-${crypto.randomUUID()}`;
const storageKey = (workspaceId: string) =>
  `${COMMERCE_STORAGE_PREFIX}${encodeURIComponent(workspaceId)}`;
function asCommerceError(error: unknown) {
  return error instanceof CommerceError
    ? error
    : new CommerceError(
        "provider",
        "The operation could not be completed. Try again.",
      );
}

/**
 * The default provider is an isolated, persistent demo. Supply an adapter from
 * a consumer's client wrapper to connect these views to their own backend.
 */
export function CommerceProvider({
  children,
  adapter,
}: {
  children: ReactNode;
  adapter?: CommerceAdapter;
}) {
  const workspace = useWorkspace();
  const workspaceId = workspace.workspaceId;
  const mode = adapter ? "stripe" : "mock";
  const initial = useMemo(() => createCommerceSeed(), []);
  const [session, setSession] = useState<Session>({
    workspaceId,
    snapshot: initial,
    ready: false,
  });
  const [busy, setBusy] = useState<string | null>(null);
  const [error, setError] = useState<CommerceError | null>(null);
  const [persistenceError, setPersistenceError] =
    useState<CommerceContextValue["persistenceError"]>(null);
  const sessionRef = useRef(session);
  const workspaceIdRef = useRef(workspaceId);
  const generationRef = useRef(0);
  const operationRef = useRef<AbortController | null>(null);
  const busyRef = useRef(false);
  const cacheRef = useRef(new Map<string, CommerceSnapshot>());
  const permissionsRef = useRef({ write: false, billing: false, ready: false });
  const canWrite = workspace.role !== "viewer";
  const canManageBilling =
    workspace.role === "owner" || workspace.role === "admin";
  useLayoutEffect(() => {
    workspaceIdRef.current = workspaceId;
    permissionsRef.current = {
      write: canWrite,
      billing: canManageBilling,
      ready: workspace.ready,
    };
  }, [workspaceId, canWrite, canManageBilling, workspace.ready]);

  const persist = useCallback((scopeId: string, snapshot: CommerceSnapshot) => {
    cacheRef.current.set(scopeId, snapshot);
    try {
      localStorage.setItem(storageKey(scopeId), JSON.stringify(snapshot));
      setPersistenceError(null);
    } catch {
      // Quota/privacy failures preserve the working in-memory session.
      setPersistenceError("write");
    }
  }, []);

  const load = useCallback(async () => {
    if (!permissionsRef.current.ready) return;
    const scopeId = workspaceId;
    operationRef.current?.abort();
    const controller = new AbortController();
    operationRef.current = controller;
    const generation = ++generationRef.current;
    busyRef.current = true;
    setBusy("load");
    setError(null);
    setPersistenceError(null);
    const pending: Session = {
      workspaceId: scopeId,
      snapshot: adapter
        ? { ...createCommerceSeed(), products: [], orders: [], invoices: [] }
        : (cacheRef.current.get(scopeId) ?? createCommerceSeed()),
      ready: false,
    };
    sessionRef.current = pending;
    setSession(pending);
    const current = () =>
      !controller.signal.aborted &&
      generationRef.current === generation &&
      workspaceIdRef.current === scopeId;
    try {
      let snapshot = pending.snapshot;
      if (adapter) {
        const response = await adapter.load({
          workspaceId: scopeId,
          signal: controller.signal,
        });
        const parsed = parseCommerceSnapshot(response);
        if (!parsed)
          throw new CommerceError(
            "provider",
            "The backend returned an invalid commerce response.",
          );
        snapshot = parsed;
      } else if (!cacheRef.current.has(scopeId)) {
        try {
          const stored = localStorage.getItem(storageKey(scopeId));
          if (stored) {
            const parsed = parseCommerceSnapshot(JSON.parse(stored));
            if (parsed) snapshot = parsed;
            else if (current()) setPersistenceError("invalid");
          }
        } catch {
          if (current()) setPersistenceError("read");
        }
      }
      if (!current()) return;
      if (!adapter) cacheRef.current.set(scopeId, snapshot);
      const next: Session = { workspaceId: scopeId, snapshot, ready: true };
      sessionRef.current = next;
      setSession(next);
    } catch (cause) {
      if (current()) {
        const failure = asCommerceError(cause);
        setError(failure);
        throw failure;
      }
    } finally {
      if (current()) {
        busyRef.current = false;
        operationRef.current = null;
        setBusy(null);
      }
    }
  }, [adapter, workspaceId]);

  useEffect(() => {
    if (workspace.ready) void load().catch(() => {});
    return () => {
      operationRef.current?.abort();
      generationRef.current += 1;
      busyRef.current = false;
    };
  }, [load, workspace.ready]);

  useEffect(() => {
    if (adapter) return;
    const receive = (event: StorageEvent) => {
      if (
        workspaceIdRef.current !== workspaceId ||
        event.key !== storageKey(workspaceId) ||
        busyRef.current
      )
        return;
      try {
        const incoming = event.newValue
          ? parseCommerceSnapshot(JSON.parse(event.newValue))
          : createCommerceSeed();
        if (!incoming) {
          setPersistenceError("invalid");
          return;
        }
        cacheRef.current.set(workspaceId, incoming);
        const next = { workspaceId, snapshot: incoming, ready: true };
        sessionRef.current = next;
        setSession(next);
        setPersistenceError(null);
      } catch {
        setPersistenceError("read");
      }
    };
    window.addEventListener("storage", receive);
    return () => window.removeEventListener("storage", receive);
  }, [adapter, workspaceId]);

  const perform = useCallback(
    async <T,>(
      label: string,
      permission: "write" | "billing",
      operation: (
        snapshot: CommerceSnapshot,
        scope: CommerceScope,
      ) => Promise<{ result: T; next?: CommerceSnapshot }>,
    ): Promise<T> => {
      const currentSession = sessionRef.current;
      if (
        !permissionsRef.current.ready ||
        !currentSession.ready ||
        currentSession.workspaceId !== workspaceIdRef.current
      )
        throw new CommerceError(
          "unavailable",
          "Wait for the workspace to finish loading.",
        );
      if (!permissionsRef.current[permission]) {
        throw new CommerceError(
          "forbidden",
          "Your workspace role cannot perform this action.",
        );
      }
      if (busyRef.current)
        throw new CommerceError(
          "conflict",
          "Another operation is still in progress.",
        );
      const scopeId = currentSession.workspaceId;
      const controller = new AbortController();
      const generation = generationRef.current;
      operationRef.current = controller;
      busyRef.current = true;
      setBusy(label);
      setError(null);
      const current = () =>
        !controller.signal.aborted &&
        generationRef.current === generation &&
        workspaceIdRef.current === scopeId;
      try {
        const { result, next } = await operation(currentSession.snapshot, {
          workspaceId: scopeId,
          signal: controller.signal,
        });
        if (!current())
          throw new CommerceError(
            "conflict",
            "The workspace changed. Review the current data.",
          );
        if (next) {
          const parsed = parseCommerceSnapshot(next);
          if (!parsed)
            throw new CommerceError(
              "validation",
              "The update contains invalid commerce data.",
            );
          const updated: Session = {
            workspaceId: scopeId,
            snapshot: parsed,
            ready: true,
          };
          sessionRef.current = updated;
          setSession(updated);
          if (!adapter) persist(scopeId, parsed);
        }
        return result;
      } catch (cause) {
        const failure = asCommerceError(cause);
        if (current()) setError(failure);
        throw failure;
      } finally {
        if (current()) {
          busyRef.current = false;
          operationRef.current = null;
          setBusy(null);
        }
      }
    },
    [adapter, persist],
  );

  const saveProduct = useCallback<CommerceContextValue["saveProduct"]>(
    (candidate) =>
      perform(`product:${candidate.id}`, "write", async (snapshot, scope) => {
        const parsed = commerceProductSchema.safeParse(candidate);
        if (!parsed.success)
          throw new CommerceError("validation", "Check the product fields.");
        const response = adapter
          ? await adapter.saveProduct(parsed.data, scope)
          : parsed.data;
        const validated = commerceProductSchema.safeParse(response);
        if (!validated.success || validated.data.id !== candidate.id) {
          throw new CommerceError(
            "provider",
            "The backend returned an invalid product.",
          );
        }
        const next = upsertCommerceProduct(
          snapshot,
          validated.data,
          adapter ? validated.data.updatedAt : now(),
        );
        return {
          result: next.products.find((item) => item.id === candidate.id)!,
          next,
        };
      }),
    [adapter, perform],
  );

  const changeProduct = useCallback(
    (id: string, action: "archive" | "sync") =>
      perform(`product:${id}`, "write", async (snapshot, scope) => {
        const product = snapshot.products.find((item) => item.id === id);
        if (!product)
          throw new CommerceError(
            "unavailable",
            "The product is no longer available.",
          );
        const response = adapter
          ? await (action === "archive"
              ? adapter.archiveProduct(id, scope)
              : adapter.syncProduct(id, scope))
          : action === "archive"
            ? { ...product, status: "archived" as const }
            : {
                ...product,
                stripeProductId: product.stripeProductId ?? `prod_demo_${id}`,
                stripePriceId:
                  product.stripePriceId ??
                  `price_demo_${crypto.randomUUID().replaceAll("-", "")}`,
              };
        const validated = commerceProductSchema.safeParse(response);
        if (!validated.success || validated.data.id !== id) {
          throw new CommerceError(
            "provider",
            "The backend returned an invalid product.",
          );
        }
        const next = upsertCommerceProduct(
          snapshot,
          validated.data,
          adapter ? validated.data.updatedAt : now(),
        );
        return { result: next.products.find((item) => item.id === id)!, next };
      }),
    [adapter, perform],
  );
  const archiveProduct = useCallback<CommerceContextValue["archiveProduct"]>(
    (id) => changeProduct(id, "archive"),
    [changeProduct],
  );
  const syncProduct = useCallback<CommerceContextValue["syncProduct"]>(
    (id) => changeProduct(id, "sync"),
    [changeProduct],
  );

  const createOrder = useCallback<CommerceContextValue["createOrder"]>(
    (input) =>
      perform("order:create", "write", async (snapshot, scope) => {
        if (snapshot.orders.length >= 1000)
          throw new CommerceError("conflict", "The demo order list is full.");
        const preview = buildOrder(
          input,
          snapshot.products,
          identifier("ord"),
          now(),
        );
        const response = adapter
          ? await adapter.createOrder(input, scope)
          : preview;
        const validated = commerceOrderSchema.safeParse(response);
        if (
          !validated.success ||
          snapshot.orders.some((item) => item.id === validated.data.id)
        ) {
          throw new CommerceError(
            "provider",
            "The backend returned an invalid order.",
          );
        }
        return {
          result: validated.data,
          next: { ...snapshot, orders: [validated.data, ...snapshot.orders] },
        };
      }),
    [adapter, perform],
  );

  const updateOrderStatus = useCallback<
    CommerceContextValue["updateOrderStatus"]
  >(
    (id, status) =>
      perform(`order:${id}`, "write", async (snapshot, scope) => {
        const order = snapshot.orders.find((item) => item.id === id);
        if (!order)
          throw new CommerceError(
            "unavailable",
            "The order is no longer available.",
          );
        if (order.status === "cancelled")
          throw new CommerceError(
            "conflict",
            "A cancelled order cannot be reopened.",
          );
        if (
          !["processing", "shipped", "delivered", "cancelled"].includes(status)
        ) {
          throw new CommerceError(
            "validation",
            "Choose an available order status.",
          );
        }
        if (
          (status === "shipped" || status === "delivered") &&
          order.paymentStatus !== "paid"
        ) {
          throw new CommerceError(
            "conflict",
            "An unpaid order cannot be shipped.",
          );
        }
        const response = adapter
          ? await adapter.updateOrderStatus(id, status, scope)
          : { ...order, status };
        const validated = commerceOrderSchema.safeParse(response);
        if (!validated.success || validated.data.id !== id)
          throw new CommerceError(
            "provider",
            "The backend returned an invalid order.",
          );
        return {
          result: validated.data,
          next: {
            ...snapshot,
            orders: snapshot.orders.map((item) =>
              item.id === id ? validated.data : item,
            ),
          },
        };
      }),
    [adapter, perform],
  );

  const createInvoice = useCallback<CommerceContextValue["createInvoice"]>(
    (input) =>
      perform("invoice:create", "write", async (snapshot, scope) => {
        const parsed = newInvoiceSchema.safeParse(input);
        if (!parsed.success)
          throw new CommerceError("validation", "Check the invoice fields.");
        if (snapshot.invoices.length >= 1000)
          throw new CommerceError("conflict", "The demo invoice list is full.");
        const createdAt = now();
        const response = adapter
          ? await adapter.createInvoice(parsed.data, scope)
          : {
              ...parsed.data,
              id: identifier("inv"),
              number: `INV-${Date.now().toString(36).toUpperCase()}`,
              status: "open" as const,
              issuedAt: createdAt,
            };
        const validated = commerceInvoiceSchema.safeParse(response);
        if (
          !validated.success ||
          snapshot.invoices.some((item) => item.id === validated.data.id)
        ) {
          throw new CommerceError(
            "provider",
            "The backend returned an invalid invoice.",
          );
        }
        return {
          result: validated.data,
          next: {
            ...snapshot,
            invoices: [validated.data, ...snapshot.invoices],
          },
        };
      }),
    [adapter, perform],
  );

  const checkout = useCallback(
    (kind: "order" | "invoice" | "subscription", id: string) =>
      perform(
        `checkout:${id}`,
        kind === "subscription" ? "billing" : "write",
        async (snapshot, scope) => {
          if (kind === "order") {
            const order = snapshot.orders.find((item) => item.id === id);
            if (
              !order ||
              order.status === "cancelled" ||
              !["unpaid", "failed"].includes(order.paymentStatus)
            ) {
              throw new CommerceError(
                "unavailable",
                "This order cannot be paid.",
              );
            }
          } else if (kind === "invoice") {
            const invoice = snapshot.invoices.find((item) => item.id === id);
            if (!invoice || !["open", "overdue"].includes(invoice.status)) {
              throw new CommerceError(
                "unavailable",
                "This invoice cannot be paid.",
              );
            }
          } else if (!commercePlans.some((item) => item.name === id)) {
            throw new CommerceError("validation", "Choose an available plan.");
          }
          const result: CommerceAction = adapter
            ? parseStripeAction(await adapter.checkout({ kind, id }, scope))
            : { mode: "mock", kind, id };
          return { result };
        },
      ),
    [adapter, perform],
  );
  const checkoutOrder = useCallback<CommerceContextValue["checkoutOrder"]>(
    (id) => checkout("order", id),
    [checkout],
  );
  const payInvoice = useCallback<CommerceContextValue["payInvoice"]>(
    (id) => checkout("invoice", id),
    [checkout],
  );
  const checkoutPlan = useCallback<CommerceContextValue["checkoutPlan"]>(
    (plan) => checkout("subscription", plan),
    [checkout],
  );
  const openPortal = useCallback<CommerceContextValue["openPortal"]>(
    () =>
      perform("portal", "billing", async (_snapshot, scope) => ({
        result: adapter
          ? parseStripeAction(await adapter.portal(scope))
          : { mode: "mock", kind: "portal", id: scope.workspaceId },
      })),
    [adapter, perform],
  );
  const simulateCheckout = useCallback<
    CommerceContextValue["simulateCheckout"]
  >(
    (action, outcome) =>
      perform(
        `simulate:${action.id}`,
        action.kind === "subscription" ? "billing" : "write",
        async (snapshot) => {
          if (adapter)
            throw new CommerceError(
              "forbidden",
              "Payment status is managed by the backend.",
            );
          return {
            result: undefined,
            next: completeMockCheckout(snapshot, action, outcome, now()),
          };
        },
      ),
    [adapter, perform],
  );
  const retryPersistence = useCallback(() => {
    const current = sessionRef.current;
    if (
      !adapter &&
      current.ready &&
      current.workspaceId === workspaceIdRef.current
    ) {
      persist(current.workspaceId, current.snapshot);
    }
  }, [adapter, persist]);

  const view = session.workspaceId === workspaceId ? session.snapshot : initial;
  const value: CommerceContextValue = {
    ...view,
    ready:
      workspace.ready && session.ready && session.workspaceId === workspaceId,
    busy,
    mode,
    error,
    persistenceError,
    canWrite,
    canManageBilling,
    reload: load,
    retryPersistence,
    saveProduct,
    archiveProduct,
    syncProduct,
    createOrder,
    updateOrderStatus,
    createInvoice,
    checkoutOrder,
    payInvoice,
    checkoutPlan,
    openPortal,
    simulateCheckout,
  };
  return <Context.Provider value={value}>{children}</Context.Provider>;
}

export function useCommerce() {
  const value = useContext(Context);
  if (!value)
    throw new Error("useCommerce must be used inside CommerceProvider.");
  return value;
}

"use client";
import { NextIntlClientProvider } from "next-intl";
import { Tooltip as TooltipPrimitive } from "@base-ui/react/tooltip";
import { Toaster } from "sonner";
import { useEffect, type ReactNode } from "react";
import { messages, type Locale } from "@/i18n/messages";
import {
  AppearanceProvider,
  useAppearance,
} from "@/components/appearance-provider";
import { WorkspaceProvider } from "@/components/workspace-provider";
import { CommerceProvider } from "@/components/commerce-provider";
import type { CommerceAdapter } from "@/lib/commerce";
import type { Theme } from "@/lib/appearance";
export function useTheme() {
  const { appearance, setAppearance } = useAppearance();
  return {
    theme: appearance.theme,
    setTheme: (theme: Theme) =>
      setAppearance((previous) => ({ ...previous, theme })),
  };
}
export function Providers({
  children,
  locale,
  commerceAdapter,
}: {
  children: ReactNode;
  locale: Locale;
  commerceAdapter?: CommerceAdapter;
}) {
  return (
    <NextIntlClientProvider
      locale={locale}
      messages={messages[locale]}
      timeZone="America/Bogota"
    >
      <AppearanceProvider>
        <WorkspaceProvider>
          <CommerceProvider adapter={commerceAdapter}>
            <ProviderContent locale={locale}>{children}</ProviderContent>
          </CommerceProvider>
        </WorkspaceProvider>
      </AppearanceProvider>
    </NextIntlClientProvider>
  );
}
function ProviderContent({
  children,
  locale,
}: {
  children: ReactNode;
  locale: Locale;
}) {
  const { appearance } = useAppearance();
  useEffect(() => {
    document.documentElement.lang = locale;
  }, [locale]);
  return (
    <TooltipPrimitive.Provider delay={300}>
      {children}
      <Toaster
        theme={appearance.theme}
        position="bottom-right"
        toastOptions={{
          style: {
            fontFamily: "var(--font-manrope)",
            background: "var(--surface)",
            color: "var(--foreground)",
            borderColor: "var(--border)",
          },
        }}
        closeButton
      />
    </TooltipPrimitive.Provider>
  );
}

"use client";
import { Fragment, useId, useState, type ReactElement } from "react";
import {
  ResponsiveContainer,
  AreaChart,
  Area,
  LineChart,
  Line,
  BarChart,
  Bar,
  PieChart,
  Pie,
  Cell,
  RadarChart,
  PolarGrid,
  PolarAngleAxis,
  PolarRadiusAxis,
  Radar,
  RadialBarChart,
  RadialBar,
  XAxis,
  YAxis,
  CartesianGrid,
  Tooltip,
  ReferenceLine,
} from "recharts";
import { cn } from "@/lib/utils";
export type ChartDatum = {
  label: string;
  value: number;
  secondary?: number;
  tertiary?: number;
};
export type ChartKind =
  | "area"
  | "line"
  | "bar"
  | "pie"
  | "radar"
  | "radial"
  | "horizontal-bar"
  | "stacked-bar"
  | "stacked-area"
  | "diverging-bar"
  | "gauge"
  | "rings"
  | "heatmap";
export type ChartSeries = "value" | "secondary" | "tertiary";
export type ChartAppearance = "flat" | "gradient" | "glow";
export type ChartProps = {
  data: ChartDatum[];
  kind?: ChartKind;
  label: string;
  valueLabel?: string;
  secondaryLabel?: string;
  tertiaryLabel?: string;
  visibleSeries?: ChartSeries[];
  legend?: boolean;
  appearance?: ChartAppearance;
  maxValue?: number;
  locale?: "en" | "es";
  height?: number;
  className?: string;
  valueFormatter?: (n: number) => string;
  axisValueFormatter?: (n: number) => string;
};
const colors = [
  "var(--chart-1)",
  "var(--chart-2)",
  "var(--chart-3)",
  "var(--chart-4)",
  "var(--chart-5)",
];
export function Chart({
  data,
  kind = "area",
  label,
  valueLabel = "Value",
  secondaryLabel = "Previous",
  tertiaryLabel = "Forecast",
  visibleSeries,
  legend = false,
  appearance = "flat",
  maxValue,
  locale = "en",
  height = 230,
  className,
  valueFormatter,
  axisValueFormatter,
}: ChartProps) {
  const id = useId().replaceAll(":", "");
  const [hidden, setHidden] = useState<string[]>([]);
  const [highlight, setHighlight] = useState<string | null>(null);
  const [point, setPoint] = useState<{
    key: string;
    label: string;
    name: string;
    value: number;
  } | null>(null);
  const hasSecondary = data.some((d) => d.secondary !== undefined);
  const hasTertiary = data.some((d) => d.tertiary !== undefined);
  const names = {
    value: valueLabel,
    secondary: secondaryLabel,
    tertiary: tertiaryLabel,
  };
  const allSeries: ChartSeries[] = [
    "value",
    ...(hasSecondary ? ["secondary" as const] : []),
    ...(hasTertiary ? ["tertiary" as const] : []),
  ];
  const series = allSeries.filter(
    (key) =>
      (!visibleSeries || visibleSeries.includes(key)) && !hidden.includes(key),
  );
  const radarSeries =
    !legend && !visibleSeries && !hasTertiary
      ? series.filter((key) => key === "value")
      : series;
  const categoryPlot = ["pie", "radial", "rings"].includes(kind);
  const categories = data.filter(
    (item) => !hidden.includes(`category:${item.label}`),
  );
  const seriesColor = (key: ChartSeries) =>
    colors[{ value: 0, secondary: 1, tertiary: 2 }[key]];
  const number = (n: number) =>
    valueFormatter?.(n) ??
    new Intl.NumberFormat(locale === "es" ? "es-CO" : "en-US", {
      maximumFractionDigits: 2,
    }).format(n);
  const compact = (n: number) =>
    new Intl.NumberFormat(locale === "es" ? "es-CO" : "en-US", {
      notation: "compact",
      maximumFractionDigits: 1,
    }).format(n);
  const total = categories.reduce((sum, item) => sum + item.value, 0);
  const goal = Math.max(1, maxValue ?? 100);
  const clamped = (value: number) => Math.max(0, Math.min(1, value / goal));
  const defs = (
    <defs>
      {allSeries.map((key) => (
        <Fragment key={key}>
          <linearGradient id={`${id}-${key}`} x1="0" y1="0" x2="0" y2="1">
            <stop
              offset="0%"
              stopColor={seriesColor(key)}
              stopOpacity={appearance === "gradient" ? 0.85 : 0.24}
            />
            <stop
              offset="100%"
              stopColor={seriesColor(key)}
              stopOpacity={appearance === "gradient" ? 0.2 : 0.02}
            />
          </linearGradient>
          <linearGradient id={`${id}-bar-${key}`} x1="0" y1="0" x2="0" y2="1">
            <stop offset="0%" stopColor={seriesColor(key)} />
            <stop
              offset="100%"
              stopColor={seriesColor(key)}
              stopOpacity={0.55}
            />
          </linearGradient>
          <linearGradient id={`${id}-line-${key}`} x1="0" y1="0" x2="1" y2="0">
            <stop offset="0%" stopColor={seriesColor(key)} />
            <stop offset="100%" stopColor="var(--foreground)" />
          </linearGradient>
        </Fragment>
      ))}
      {colors.map((color, index) => (
        <linearGradient
          key={color}
          id={`${id}-category-${index}`}
          x1="0"
          y1="0"
          x2="1"
          y2="1"
        >
          <stop offset="0%" stopColor={color} />
          <stop
            offset="100%"
            stopColor="var(--foreground)"
            stopOpacity={0.65}
          />
        </linearGradient>
      ))}
      <filter id={`${id}-glow`} x="-25%" y="-25%" width="150%" height="150%">
        <feGaussianBlur stdDeviation="2.5" result="blur" />
        <feMerge>
          <feMergeNode in="blur" />
          <feMergeNode in="SourceGraphic" />
        </feMerge>
      </filter>
    </defs>
  );
  const glow = appearance === "glow" ? `url(#${id}-glow)` : undefined;
  const axis = {
    tickLine: false,
    axisLine: false,
    tick: { fill: "var(--muted-foreground)", fontSize: 10 },
  };
  const tooltip = (
    <Tooltip
      contentStyle={{
        background: "var(--surface)",
        border: "1px solid var(--border)",
        borderRadius: 12,
        fontSize: 11,
        color: "var(--foreground)",
        boxShadow: "var(--af-shadow-soft)",
      }}
      labelStyle={{ color: "var(--foreground)", fontWeight: 600 }}
      itemStyle={{ color: "var(--foreground)" }}
      cursor={{
        stroke: "var(--border)",
        fill: "var(--surface-subtle)",
        fillOpacity: 0.25,
      }}
      isAnimationActive={false}
      labelFormatter={(fallback, payload) =>
        payload?.[0]?.payload?.label ?? fallback
      }
      formatter={(value, name) => [number(Number(value)), name]}
    />
  );
  const cartesian = (
    <>
      <CartesianGrid
        vertical={false}
        stroke="var(--border)"
        strokeDasharray="3 5"
      />
      <XAxis dataKey="label" {...axis} dy={8} minTickGap={22} />
      <YAxis
        {...axis}
        width={42}
        tickFormatter={(n) =>
          axisValueFormatter?.(n) ??
          valueFormatter?.(n) ??
          (Math.abs(n) >= 1000 ? `${n / 1000}k` : String(n))
        }
      />
      {tooltip}
    </>
  );
  let plot: ReactElement;
  if (kind === "pie")
    plot = (
      <PieChart>
        {defs}
        {tooltip}
        <Pie
          data={categories}
          isAnimationActive={false}
          dataKey="value"
          nameKey="label"
          innerRadius="60%"
          outerRadius="90%"
          paddingAngle={4}
          stroke="none"
          filter={glow}
        >
          {categories.map((item) => {
            const index = data.indexOf(item) % colors.length;
            return (
              <Cell
                key={item.label}
                fill={
                  appearance === "gradient"
                    ? `url(#${id}-category-${index})`
                    : colors[index]
                }
                stroke={
                  highlight === `category:${item.label}`
                    ? "var(--foreground)"
                    : colors[index]
                }
                strokeWidth={highlight === `category:${item.label}` ? 2 : 1}
              />
            );
          })}
        </Pie>
      </PieChart>
    );
  else if (kind === "radar")
    plot = (
      <RadarChart data={data}>
        {defs}
        <PolarGrid stroke="var(--border)" />
        <PolarAngleAxis
          dataKey="label"
          tick={{ fill: "var(--muted-foreground)", fontSize: 10 }}
        />
        <PolarRadiusAxis tick={false} axisLine={false} />
        {radarSeries.map((key) => (
          <Radar
            key={key}
            dataKey={key}
            isAnimationActive={false}
            name={names[key]}
            fill={seriesColor(key)}
            fillOpacity={0.12}
            stroke={seriesColor(key)}
            strokeWidth={highlight === key ? 3 : 2}
            filter={glow}
          />
        ))}
        {tooltip}
      </RadarChart>
    );
  else if (kind === "radial")
    plot = (
      <RadialBarChart
        data={categories.map((d) => ({
          ...d,
          fill: colors[data.indexOf(d) % colors.length],
        }))}
        innerRadius="30%"
        outerRadius="95%"
        startAngle={180}
        endAngle={-180}
      >
        {defs}
        {maxValue !== undefined && (
          <PolarAngleAxis type="number" domain={[0, goal]} tick={false} />
        )}
        <RadialBar
          dataKey="value"
          name={valueLabel}
          isAnimationActive={false}
          background={{ fill: "var(--surface-subtle)" }}
          cornerRadius={6}
          filter={glow}
        >
          {categories.map((item) => {
            const index = data.indexOf(item) % colors.length;
            return (
              <Cell
                key={item.label}
                fill={
                  appearance === "gradient"
                    ? `url(#${id}-category-${index})`
                    : colors[index]
                }
                stroke={
                  highlight === `category:${item.label}`
                    ? "var(--foreground)"
                    : colors[index]
                }
                strokeWidth={highlight === `category:${item.label}` ? 2 : 1}
              />
            );
          })}
        </RadialBar>
        {tooltip}
      </RadialBarChart>
    );
  else if (kind === "gauge")
    plot = (
      <RadialBarChart
        data={[
          {
            ...data[0],
            value: Math.max(0, data[0]?.value ?? 0),
            fill: colors[0],
          },
        ]}
        cx="50%"
        cy="80%"
        innerRadius="70%"
        outerRadius="95%"
        startAngle={180}
        endAngle={0}
      >
        {defs}
        <PolarAngleAxis type="number" domain={[0, goal]} tick={false} />
        <RadialBar
          dataKey="value"
          name={valueLabel}
          isAnimationActive={false}
          background={{ fill: "var(--surface-subtle)" }}
          cornerRadius={12}
          filter={glow}
        >
          <Cell
            fill={
              appearance === "gradient" ? `url(#${id}-category-0)` : colors[0]
            }
            stroke={colors[0]}
            strokeWidth={1}
          />
        </RadialBar>
        {tooltip}
      </RadialBarChart>
    );
  else if (
    ["bar", "horizontal-bar", "stacked-bar", "diverging-bar"].includes(kind)
  )
    plot = (
      <BarChart
        data={data}
        barGap={3}
        layout={kind === "horizontal-bar" ? "vertical" : "horizontal"}
        stackOffset={kind === "diverging-bar" ? "sign" : "none"}
        margin={{ top: 10, right: 6, left: 0, bottom: 8 }}
      >
        {defs}
        {kind === "horizontal-bar" ? (
          <>
            <CartesianGrid
              horizontal={false}
              stroke="var(--border)"
              strokeDasharray="3 5"
            />
            <XAxis
              type="number"
              {...axis}
              tickFormatter={(n) =>
                axisValueFormatter?.(n) ??
                (Math.abs(n) >= 1000 ? `${n / 1000}k` : String(n))
              }
            />
            <YAxis
              type="category"
              dataKey="label"
              {...axis}
              width={64}
              interval={0}
            />
            {tooltip}
          </>
        ) : (
          cartesian
        )}
        {kind === "diverging-bar" && (
          <ReferenceLine y={0} stroke="var(--muted-foreground)" />
        )}
        {series.map((key) => (
          <Bar
            key={key}
            dataKey={key}
            isAnimationActive={false}
            name={names[key]}
            fill={
              appearance === "gradient"
                ? `url(#${id}-bar-${key})`
                : seriesColor(key)
            }
            stroke={seriesColor(key)}
            strokeWidth={1}
            stackId={
              kind === "stacked-bar" || kind === "diverging-bar"
                ? "values"
                : undefined
            }
            radius={kind === "horizontal-bar" ? [0, 5, 5, 0] : [4, 4, 4, 4]}
            maxBarSize={kind === "horizontal-bar" ? 16 : 26}
            filter={glow}
          />
        ))}
      </BarChart>
    );
  else if (kind === "line")
    plot = (
      <LineChart data={data} margin={{ top: 10, right: 6, left: 0, bottom: 8 }}>
        {cartesian}
        {defs}
        {series.map((key) => (
          <Line
            key={key}
            type="monotone"
            dataKey={key}
            isAnimationActive={false}
            name={names[key]}
            stroke={
              appearance === "gradient"
                ? `url(#${id}-line-${key})`
                : seriesColor(key)
            }
            strokeWidth={highlight === key ? 3 : 2}
            strokeDasharray={key === "secondary" ? "4 4" : undefined}
            dot={false}
            activeDot={{ r: 5, stroke: "var(--surface)", strokeWidth: 2 }}
            filter={glow}
          />
        ))}
      </LineChart>
    );
  else if (kind === "area" || kind === "stacked-area")
    plot = (
      <AreaChart data={data} margin={{ top: 10, right: 6, left: 0, bottom: 8 }}>
        {defs}
        {cartesian}
        {[...series].reverse().map((key) => (
          <Area
            key={key}
            type="monotone"
            dataKey={key}
            isAnimationActive={false}
            name={names[key]}
            stackId={kind === "stacked-area" ? "values" : undefined}
            stroke={seriesColor(key)}
            strokeWidth={highlight === key ? 3 : 2}
            strokeDasharray={
              kind === "area" && key === "secondary" ? "4 4" : undefined
            }
            fill={
              kind === "stacked-area" || key === "value"
                ? `url(#${id}-${key})`
                : "transparent"
            }
            filter={glow}
          />
        ))}
      </AreaChart>
    );
  else if (kind === "rings") {
    const shown = categories;
    const spacing = Math.min(13, 76 / Math.max(1, shown.length));
    const ringWidth = Math.min(8, spacing * 0.66);
    plot = (
      <svg viewBox="0 0 260 230" width="100%" height="100%" aria-label={label}>
        {defs}
        {shown.map((item, index) => {
          const radius = 96 - index * spacing;
          const circumference = 2 * Math.PI * radius;
          const key = `category:${item.label}`;
          const inspect = () =>
            setPoint({
              key,
              label: item.label,
              name: valueLabel,
              value: item.value,
            });
          return (
            <g
              key={item.label}
              tabIndex={0}
              role="graphics-symbol"
              aria-label={`${item.label}: ${number(item.value)}`}
              className="outline-none focus-visible:stroke-foreground"
              onPointerEnter={inspect}
              onPointerLeave={() => setPoint(null)}
              onFocus={inspect}
              onBlur={() => setPoint(null)}
              onClick={inspect}
            >
              <circle
                cx="130"
                cy="110"
                r={radius}
                fill="none"
                stroke="var(--surface-subtle)"
                strokeWidth={ringWidth}
              />
              <circle
                cx="130"
                cy="110"
                r={radius}
                fill="none"
                stroke={colors[data.indexOf(item) % colors.length]}
                strokeWidth={
                  highlight === key || point?.key === key
                    ? ringWidth + 1.5
                    : ringWidth
                }
                strokeLinecap="round"
                filter={glow}
                strokeDasharray={`${circumference * clamped(item.value)} ${circumference}`}
                transform="rotate(-90 130 110)"
              />
              {appearance === "gradient" && (
                <circle
                  cx="130"
                  cy="110"
                  r={radius}
                  fill="none"
                  stroke={`url(#${id}-category-${data.indexOf(item) % colors.length})`}
                  strokeWidth={ringWidth * 0.7}
                  strokeLinecap="round"
                  strokeDasharray={`${circumference * clamped(item.value)} ${circumference}`}
                  transform="rotate(-90 130 110)"
                />
              )}
              <title>{`${item.label}: ${number(item.value)}`}</title>
            </g>
          );
        })}
        <text
          x="130"
          y="108"
          textAnchor="middle"
          fill="var(--foreground)"
          fontSize={shown.length > 6 ? 16 : 24}
          fontWeight="600"
        >
          {Math.round(
            (shown.reduce((sum, item) => sum + clamped(item.value), 0) /
              Math.max(1, shown.length)) *
              100,
          )}
          %
        </text>
        <text
          x="130"
          y="127"
          textAnchor="middle"
          fill="var(--muted-foreground)"
          fontSize="10"
        >
          {locale === "es" ? "Promedio" : "Average"}
        </text>
      </svg>
    );
  } else {
    const svgHeight = Math.max(210, data.length * 24 + 40);
    const columnWidth = 246 / Math.max(1, series.length);
    const peak = Math.max(
      1,
      ...data.flatMap((item) => series.map((key) => Math.abs(item[key] ?? 0))),
    );
    plot = (
      <svg
        viewBox={`0 0 320 ${svgHeight}`}
        width="100%"
        height="100%"
        aria-label={label}
      >
        {defs}
        {series.map((key, column) => (
          <text
            key={key}
            x={66 + columnWidth * (column + 0.5)}
            y="16"
            textAnchor="middle"
            fill="var(--muted-foreground)"
            fontSize="10"
          >
            {names[key]}
          </text>
        ))}
        {data.map((item, row) => (
          <g key={`${item.label}-${row}`}>
            <text
              x="56"
              y={42 + row * 24}
              textAnchor="end"
              fill="var(--muted-foreground)"
              fontSize="10"
            >
              {item.label.length > 10
                ? `${item.label.slice(0, 9)}…`
                : item.label}
            </text>
            {series.map((key, column) => {
              const value = item[key] ?? 0;
              const cellKey = `${row}:${key}`;
              const inspect = () =>
                setPoint({
                  key: cellKey,
                  label: item.label,
                  name: names[key],
                  value,
                });
              return (
                <g
                  key={key}
                  tabIndex={0}
                  role="graphics-symbol"
                  aria-label={`${item.label}, ${names[key]}: ${number(value)}`}
                  className="outline-none focus-visible:stroke-foreground"
                  onPointerEnter={inspect}
                  onPointerLeave={() => setPoint(null)}
                  onFocus={inspect}
                  onBlur={() => setPoint(null)}
                  onClick={inspect}
                >
                  <rect
                    x={66 + column * columnWidth}
                    y={28 + row * 24}
                    width={columnWidth - 6}
                    height="19"
                    rx="4"
                    fill={
                      appearance === "gradient"
                        ? `url(#${id}-bar-${key})`
                        : seriesColor(key)
                    }
                    fillOpacity={0.18 + (Math.abs(value) / peak) * 0.82}
                    stroke={
                      point?.key === cellKey
                        ? "var(--foreground)"
                        : seriesColor(key)
                    }
                    strokeWidth="1"
                    filter={glow}
                  />
                  <title>{`${item.label}, ${names[key]}: ${number(value)}`}</title>
                </g>
              );
            })}
          </g>
        ))}
      </svg>
    );
  }
  const legendItems = categoryPlot
    ? data.map((item, index) => ({
        key: `category:${item.label}`,
        name: item.label,
        color: colors[index % colors.length],
      }))
    : allSeries
        .filter((key) => !visibleSeries || visibleSeries.includes(key))
        .map((key) => ({ key, name: names[key], color: seriesColor(key) }));
  const activeCount = legendItems.filter(
    (item) => !hidden.includes(item.key),
  ).length;
  return (
    <div
      className={cn("chart-shell min-w-0", className)}
      style={{ width: "100%" }}
    >
      <div
        role="group"
        aria-label={label}
        className="relative min-w-0 rounded-xl bg-surface"
        style={{ height }}
        onKeyDown={(event) => {
          if (event.key === "Escape") setPoint(null);
        }}
      >
        {kind === "rings" || kind === "heatmap" ? (
          plot
        ) : (
          <ResponsiveContainer
            width="100%"
            height="100%"
            minWidth={0}
            initialDimension={{ width: 500, height }}
          >
            {plot}
          </ResponsiveContainer>
        )}
        {kind === "pie" && categories.length > 0 && (
          <div className="pointer-events-none absolute inset-0 grid place-content-center text-center">
            <span className="text-2xl font-semibold tracking-tight tabular-nums">
              {compact(total)}
            </span>
            <span className="mt-1 text-[10px] text-muted-foreground">
              Total
            </span>
          </div>
        )}
        {kind === "gauge" && data.length > 0 && (
          <div className="pointer-events-none absolute inset-x-0 bottom-6 text-center">
            <span className="text-3xl font-semibold tracking-tight tabular-nums">
              {number(data[0].value)}
            </span>
            <p className="mt-1 text-[10px] text-muted-foreground">
              {locale === "es" ? "de" : "of"} {number(goal)}
            </p>
          </div>
        )}
        {point && (
          <div
            role="status"
            className="pointer-events-none absolute inset-x-2 bottom-1 rounded-lg border border-border bg-surface/95 px-3 py-2 text-[11px] shadow-lg"
          >
            <span className="font-semibold">{point.label}</span>
            <span className="ml-2 text-muted-foreground">{point.name}: </span>
            <span className="font-medium tabular-nums">
              {number(point.value)}
            </span>
          </div>
        )}
      </div>
      {legend && (
        <div
          className="mt-3 flex flex-wrap justify-center gap-1.5"
          aria-label={locale === "es" ? "Leyenda del gráfico" : "Chart legend"}
        >
          {legendItems.map((item) => {
            const selected = !hidden.includes(item.key);
            return (
              <button
                key={item.key}
                type="button"
                aria-pressed={selected}
                disabled={selected && activeCount === 1}
                aria-label={`${item.name}: ${locale === "es" ? (selected ? "ocultar" : "mostrar") : selected ? "hide" : "show"}`}
                onClick={() =>
                  setHidden((current) =>
                    selected
                      ? [...current, item.key]
                      : current.filter((key) => key !== item.key),
                  )
                }
                onPointerEnter={() => setHighlight(item.key)}
                onPointerLeave={() => setHighlight(null)}
                onFocus={() => setHighlight(item.key)}
                onBlur={() => setHighlight(null)}
                className={cn(
                  "flex min-h-8 items-center gap-1.5 rounded-md border border-transparent px-2 text-[10px] outline-none hover:border-border focus-visible:ring-2 focus-visible:ring-ring",
                  !selected && "text-muted-foreground line-through",
                )}
              >
                <span
                  aria-hidden="true"
                  className="size-2 rounded-full"
                  style={{ background: item.color }}
                />
                {item.name}
              </button>
            );
          })}
        </div>
      )}
      <div className="sr-only">
        <table>
          <caption>{label}</caption>
          <thead>
            <tr>
              <th scope="col">{label}</th>
              <th scope="col">{valueLabel}</th>
              {hasSecondary && <th scope="col">{secondaryLabel}</th>}
              {hasTertiary && <th scope="col">{tertiaryLabel}</th>}
            </tr>
          </thead>
          <tbody>
            {data.map((d, index) => (
              <tr key={`${d.label}-${index}`}>
                <th scope="row">{d.label}</th>
                <td>{d.value}</td>
                {hasSecondary && <td>{d.secondary}</td>}
                {hasTertiary && <td>{d.tertiary}</td>}
              </tr>
            ))}
          </tbody>
        </table>
      </div>
    </div>
  );
}

"use client";

import {
  createContext,
  useCallback,
  useContext,
  useEffect,
  useMemo,
  useRef,
  useState,
  type Dispatch,
  type ReactNode,
  type SetStateAction,
} from "react";
import { createSaasSeed } from "@/demo/saas-data";
import type { Customer } from "@/demo/dashboard-data";
import {
  SAAS_STORAGE_KEY,
  SaasError,
  changeWorkspaceMemberRole,
  customerSchema,
  hasCapability,
  mergeImportedCustomers,
  parseSaasState,
  removeWorkspaceMember,
  transferWorkspaceOwnership,
  updateWorkspaceData,
  workspaceInputSchema,
  type CustomerNote,
  type CustomerAttachment,
  type CustomerImportResult,
  type InviteRole,
  type OnboardingDraft,
  type SaasDemoState,
  type SavedWorkspaceView,
  type Workspace,
  type WorkspaceActivity,
  type WorkspaceCapability,
  type WorkspaceData,
  type WorkspaceInvitation,
  type WorkspaceMember,
  type WorkspaceRole,
} from "@/lib/saas";

type WorkspaceInput = Omit<Workspace, "id">;
export type WorkspaceContextValue = {
  ready: boolean;
  persistenceError: "read" | "write" | "invalid" | null;
  workspace: Workspace;
  workspaces: Workspace[];
  workspaceId: string;
  currentMemberId: string;
  currentMember: WorkspaceMember;
  role: WorkspaceRole;
  previewRole: WorkspaceRole | null;
  setPreviewRole: (role: WorkspaceRole | null) => void;
  can: (capability: WorkspaceCapability) => boolean;
  setWorkspace: (id: string) => void;
  createWorkspace: (input: WorkspaceInput) => Workspace;
  updateWorkspace: (input: WorkspaceInput) => void;
  customers: Customer[];
  setCustomers: Dispatch<SetStateAction<Customer[]>>;
  importCustomers: (
    rows: readonly Customer[],
    mode: "skip" | "update",
  ) => CustomerImportResult;
  members: WorkspaceMember[];
  invitations: WorkspaceInvitation[];
  inviteMember: (email: string, role: InviteRole) => void;
  resendInvitation: (id: string) => void;
  acceptInvitation: (id: string) => void;
  revokeInvitation: (id: string) => void;
  changeMemberRole: (id: string, role: WorkspaceRole) => void;
  removeMember: (id: string) => void;
  transferOwnership: (id: string) => void;
  notes: Record<string, CustomerNote[]>;
  addNote: (customerId: string, text: string) => void;
  files: Record<string, CustomerAttachment[]>;
  attachFiles: (customerId: string, files: readonly File[]) => void;
  activity: WorkspaceActivity[];
  recordActivity: (
    detail: string,
    kind: WorkspaceActivity["kind"],
    resourceId?: string,
  ) => void;
  savedViews: SavedWorkspaceView[];
  setSavedViews: Dispatch<SetStateAction<SavedWorkspaceView[]>>;
  customerView: unknown;
  setCustomerView: (value: unknown) => void;
  onboarding: OnboardingDraft;
  setOnboarding: (value: OnboardingDraft) => void;
  completeOnboarding: (value: OnboardingDraft) => void;
  retryPersistence: () => void;
};

const Context = createContext<WorkspaceContextValue | null>(null);
const id = (prefix: string) => `${prefix}-${crypto.randomUUID()}`;

export function WorkspaceProvider({ children }: { children: ReactNode }) {
  const [state, setState] = useState<SaasDemoState>(createSaasSeed);
  const [ready, setReady] = useState(false);
  const [persistenceError, setPersistenceError] =
    useState<WorkspaceContextValue["persistenceError"]>(null);
  const stateRef = useRef(state);

  useEffect(() => {
    try {
      const stored = localStorage.getItem(SAAS_STORAGE_KEY);
      if (stored) {
        const parsed = parseSaasState(JSON.parse(stored));
        if (parsed) {
          stateRef.current = parsed;
          setState(parsed);
        } else {
          setPersistenceError("invalid");
        }
      }
    } catch {
      setPersistenceError("read");
    }
    setReady(true);
    const receive = (event: StorageEvent) => {
      if (event.key !== SAAS_STORAGE_KEY || !event.newValue) return;
      try {
        const incoming = parseSaasState(JSON.parse(event.newValue));
        if (!incoming) {
          setPersistenceError("invalid");
          return;
        }
        stateRef.current = incoming;
        setState(incoming);
      } catch {
        setPersistenceError("read");
      }
    };
    window.addEventListener("storage", receive);
    return () => window.removeEventListener("storage", receive);
  }, []);
  useEffect(() => {
    if (!ready) return;
    try {
      localStorage.setItem(SAAS_STORAGE_KEY, JSON.stringify(state));
    } catch {
      setPersistenceError("write");
    }
  }, [ready, state]);

  // Validate synchronously, then commit once. Errors remain catchable by callers.
  const commit = useCallback(
    (updater: (previous: SaasDemoState) => SaasDemoState) => {
      const next = updater(stateRef.current);
      stateRef.current = next;
      setState(next);
    },
    [],
  );
  const previewRole = state.previewRole ?? null;
  const setPreviewRole = useCallback(
    (next: WorkspaceRole | null) => {
      commit((previous) => ({ ...previous, previewRole: next ?? undefined }));
    },
    [commit],
  );
  const workspaceId = state.activeWorkspaceId;
  const data = state.data[workspaceId];
  const workspace = state.workspaces.find((item) => item.id === workspaceId)!;
  const currentMember = data.members.find(
    (item) => item.id === state.currentMemberId,
  )!;
  const role = previewRole ?? currentMember.role;
  const can = useCallback(
    (capability: WorkspaceCapability) => hasCapability(role, capability),
    [role],
  );
  const assert = useCallback(
    (capability: WorkspaceCapability) => {
      const snapshot = stateRef.current;
      const actor = snapshot.data[workspaceId]?.members.find(
        (member) => member.id === snapshot.currentMemberId,
      );
      const liveRole = snapshot.previewRole ?? actor?.role;
      if (
        !ready ||
        snapshot.activeWorkspaceId !== workspaceId ||
        actor?.status !== "active" ||
        !liveRole ||
        !hasCapability(liveRole, capability)
      )
        throw new SaasError("permission");
    },
    [ready, workspaceId],
  );
  const updateData = useCallback(
    (updater: (previous: WorkspaceData) => WorkspaceData) => {
      commit((previous) => updateWorkspaceData(previous, workspaceId, updater));
    },
    [commit, workspaceId],
  );
  const newActivity = useCallback(
    (
      detail: string,
      kind: WorkspaceActivity["kind"],
      resourceId?: string,
    ): WorkspaceActivity => ({
      id: id("event"),
      actor: currentMember.name,
      detail,
      kind,
      resourceId,
      occurredAt: new Date().toISOString(),
    }),
    [currentMember.name],
  );
  const recordActivity = useCallback(
    (detail: string, kind: WorkspaceActivity["kind"], resourceId?: string) => {
      const activity = newActivity(detail, kind, resourceId);
      updateData((previous) => ({
        ...previous,
        activity: [activity, ...previous.activity].slice(0, 2000),
      }));
    },
    [newActivity, updateData],
  );

  const setWorkspace = useCallback(
    (targetId: string) => {
      const previous = stateRef.current;
      if (!previous.workspaces.some((item) => item.id === targetId))
        throw new SaasError("missing");
      setPreviewRole(null);
      commit((snapshot) => ({ ...snapshot, activeWorkspaceId: targetId }));
    },
    [commit, setPreviewRole],
  );
  const createWorkspace = useCallback(
    (input: WorkspaceInput) => {
      if (!ready || role === "viewer") throw new SaasError("permission");
      const parsed = workspaceInputSchema.safeParse(input);
      if (!parsed.success) throw new SaasError("invalid");
      if (
        stateRef.current.workspaces.some(
          (item) => item.slug === parsed.data.slug,
        )
      )
        throw new SaasError("duplicate");
      const created: Workspace = { id: id("workspace"), ...parsed.data };
      const member = {
        ...currentMember,
        role: "owner" as const,
        status: "active" as const,
      };
      commit((previous) => ({
        ...previous,
        activeWorkspaceId: created.id,
        workspaces: [...previous.workspaces, created],
        data: {
          ...previous.data,
          [created.id]: {
            customers: [],
            members: [member],
            invitations: [],
            notes: {},
            activity: [],
            savedViews: [],
          },
        },
      }));
      setPreviewRole(null);
      return created;
    },
    [commit, currentMember, ready, role, setPreviewRole],
  );
  const updateWorkspace = useCallback(
    (input: WorkspaceInput) => {
      assert("workspace.manage");
      const parsed = workspaceInputSchema.safeParse(input);
      if (!parsed.success) throw new SaasError("invalid");
      if (
        stateRef.current.workspaces.some(
          (item) => item.id !== workspaceId && item.slug === parsed.data.slug,
        )
      )
        throw new SaasError("duplicate");
      commit((previous) => ({
        ...previous,
        workspaces: previous.workspaces.map((item) =>
          item.id === workspaceId ? { ...item, ...parsed.data } : item,
        ),
      }));
      recordActivity("Workspace updated · Workspace actualizado", "workspace");
    },
    [assert, commit, recordActivity, workspaceId],
  );
  const setCustomers = useCallback<Dispatch<SetStateAction<Customer[]>>>(
    (next) => {
      assert("customers.write");
      updateData((previous) => {
        const candidates =
          typeof next === "function" ? next(previous.customers) : next;
        const parsed = candidates.map((candidate) =>
          customerSchema.safeParse(candidate),
        );
        if (parsed.length > 25000 || parsed.some((item) => !item.success))
          throw new SaasError("invalid");
        const records = parsed.map((item) => item.data!);
        if (
          new Set(records.map((item) => item.id)).size !== records.length ||
          new Set(records.map((item) => item.email.toLowerCase())).size !==
            records.length
        )
          throw new SaasError("duplicate");
        return { ...previous, customers: records };
      });
    },
    [assert, updateData],
  );
  const setSavedViews = useCallback<
    Dispatch<SetStateAction<SavedWorkspaceView[]>>
  >(
    (next) => {
      assert("views.manage");
      updateData((previous) => ({
        ...previous,
        savedViews:
          typeof next === "function" ? next(previous.savedViews) : next,
      }));
    },
    [assert, updateData],
  );
  const setCustomerView = useCallback(
    (next: unknown) => {
      updateData((previous) => ({ ...previous, customerView: next }));
    },
    [updateData],
  );
  const importCustomers = useCallback(
    (rows: readonly Customer[], mode: "skip" | "update") => {
      assert("customers.import");
      const current = stateRef.current.data[workspaceId];
      const merged = mergeImportedCustomers(current.customers, [...rows], mode);
      updateData((previous) => ({ ...previous, customers: merged.customers }));
      recordActivity(
        `Customers imported: ${merged.result.created + merged.result.updated} · Clientes importados: ${merged.result.created + merged.result.updated}`,
        "import",
      );
      return merged.result;
    },
    [assert, recordActivity, updateData, workspaceId],
  );
  const inviteMember = useCallback(
    (rawEmail: string, inviteRole: InviteRole) => {
      assert("members.manage");
      const email = rawEmail.trim().toLowerCase();
      if (
        !/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email) ||
        !["admin", "member", "viewer"].includes(inviteRole)
      )
        throw new SaasError("invalid");
      const previous = stateRef.current.data[workspaceId];
      if (
        previous.members.some((item) => item.email.toLowerCase() === email) ||
        previous.invitations.some(
          (item) =>
            item.email.toLowerCase() === email && item.status === "pending",
        )
      )
        throw new SaasError("duplicate");
      const invitation: WorkspaceInvitation = {
        id: id("invite"),
        email,
        role: inviteRole,
        status: "pending",
        expiresAt: new Date(Date.now() + 7 * 86400000).toISOString(),
      };
      updateData((snapshot) => ({
        ...snapshot,
        invitations: [...snapshot.invitations, invitation],
      }));
      recordActivity(
        `Invitation created · Invitación creada: ${email}`,
        "member",
      );
    },
    [assert, recordActivity, updateData, workspaceId],
  );
  const changeInvitation = useCallback(
    (targetId: string, status: "pending" | "revoked") => {
      assert("members.manage");
      const target = stateRef.current.data[workspaceId].invitations.find(
        (item) => item.id === targetId,
      );
      if (
        !target ||
        target.status === "accepted" ||
        target.status === "revoked"
      )
        throw new SaasError("invalid");
      const expiresAt = new Date(Date.now() + 7 * 86400000).toISOString();
      updateData((previous) => ({
        ...previous,
        invitations: previous.invitations.map((item) =>
          item.id === targetId
            ? {
                ...item,
                status,
                ...(status === "pending" ? { expiresAt } : {}),
              }
            : item,
        ),
      }));
      recordActivity(
        status === "pending"
          ? "Invitation renewed · Invitación renovada"
          : "Invitation revoked · Invitación revocada",
        "member",
      );
    },
    [assert, recordActivity, updateData, workspaceId],
  );
  const acceptInvitation = useCallback(
    (targetId: string) => {
      assert("members.manage");
      const snapshot = stateRef.current.data[workspaceId];
      const target = snapshot.invitations.find((item) => item.id === targetId);
      if (!target || target.status !== "pending")
        throw new SaasError("invalid");
      if (Date.parse(target.expiresAt) <= Date.now())
        throw new SaasError("expired");
      if (
        snapshot.members.some(
          (member) => member.email.toLowerCase() === target.email.toLowerCase(),
        )
      )
        throw new SaasError("duplicate");
      const member: WorkspaceMember = {
        id: id("member"),
        name: target.email.split("@")[0],
        email: target.email,
        role: target.role,
        status: "active",
        joinedAt: new Date().toISOString().slice(0, 10),
      };
      updateData((previous) => ({
        ...previous,
        members: [...previous.members, member],
        invitations: previous.invitations.map((item) =>
          item.id === targetId ? { ...item, status: "accepted" } : item,
        ),
      }));
      recordActivity(
        `Member joined · Miembro incorporado: ${target.email}`,
        "member",
      );
    },
    [assert, recordActivity, updateData, workspaceId],
  );
  const changeMemberRole = useCallback(
    (targetId: string, nextRole: WorkspaceRole) => {
      assert("members.manage");
      updateData((previous) => ({
        ...previous,
        members: changeWorkspaceMemberRole(
          previous.members,
          targetId,
          nextRole,
          stateRef.current.currentMemberId,
        ),
      }));
      recordActivity(
        "Member role changed · Rol de miembro actualizado",
        "member",
      );
    },
    [assert, recordActivity, updateData],
  );
  const removeMember = useCallback(
    (targetId: string) => {
      assert("members.manage");
      updateData((previous) => ({
        ...previous,
        members: removeWorkspaceMember(
          previous.members,
          stateRef.current.currentMemberId,
          targetId,
        ),
      }));
      recordActivity("Member removed · Miembro eliminado", "member");
    },
    [assert, recordActivity, updateData],
  );
  const transferOwnership = useCallback(
    (targetId: string) => {
      assert("ownership.transfer");
      updateData((previous) => ({
        ...previous,
        members: transferWorkspaceOwnership(
          previous.members,
          stateRef.current.currentMemberId,
          targetId,
        ),
      }));
      setPreviewRole(null);
      recordActivity(
        "Ownership transferred · Titularidad transferida",
        "member",
      );
    },
    [assert, recordActivity, setPreviewRole, updateData],
  );
  const addNote = useCallback(
    (customerId: string, rawText: string) => {
      assert("notes.write");
      const text = rawText.trim();
      if (!text || text.length > 10000) throw new SaasError("invalid");
      if (
        !stateRef.current.data[workspaceId].customers.some(
          (item) => item.id === customerId,
        )
      )
        throw new SaasError("missing");
      const note: CustomerNote = {
        id: id("note"),
        text,
        author: currentMember.name,
        authorMemberId: currentMember.id,
        createdAt: new Date().toISOString(),
      };
      updateData((previous) => ({
        ...previous,
        notes: {
          ...previous.notes,
          [customerId]: [...(previous.notes[customerId] ?? []), note],
        },
      }));
      recordActivity("Note added · Nota añadida", "note", customerId);
    },
    [
      assert,
      currentMember.id,
      currentMember.name,
      recordActivity,
      updateData,
      workspaceId,
    ],
  );
  const attachFiles = useCallback(
    (customerId: string, files: readonly File[]) => {
      assert("customers.write");
      const current = stateRef.current.data[workspaceId];
      if (!current.customers.some((item) => item.id === customerId))
        throw new SaasError("missing");
      const existing = current.files?.[customerId] ?? [];
      if (
        !files.length ||
        existing.length + files.length > 100 ||
        files.some(
          (file) =>
            !file.name ||
            file.name.length > 255 ||
            file.size > 10 * 1024 * 1024,
        )
      )
        throw new SaasError("invalid");
      const additions: CustomerAttachment[] = files.map((file) => ({
        id: id("file"),
        name: file.name,
        size: file.size,
        type: file.type,
        createdAt: new Date().toISOString(),
      }));
      updateData((previous) => ({
        ...previous,
        files: {
          ...previous.files,
          [customerId]: [...(previous.files?.[customerId] ?? []), ...additions],
        },
      }));
      recordActivity(
        `File details added: ${files.length} · Datos de archivos añadidos: ${files.length}`,
        "customer",
        customerId,
      );
    },
    [assert, recordActivity, updateData, workspaceId],
  );
  const setOnboarding = useCallback(
    (value: OnboardingDraft) => {
      commit((previous) => ({ ...previous, onboarding: value }));
    },
    [commit],
  );
  const completeOnboarding = useCallback(
    (value: OnboardingDraft) => {
      const existing = stateRef.current.onboarding;
      if (existing.completed && existing.workspaceId) {
        setWorkspace(existing.workspaceId);
        return;
      }
      const emails = value.invites.map((item) =>
        item.email.trim().toLowerCase(),
      );
      if (
        value.invites.length > 50 ||
        value.invites.some(
          (item) => !["admin", "member", "viewer"].includes(item.role),
        ) ||
        emails.some((email) => !/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email))
      )
        throw new SaasError("invalid");
      if (
        new Set(emails).size !== emails.length ||
        emails.includes(currentMember.email.toLowerCase())
      )
        throw new SaasError("duplicate");
      const created = createWorkspace({
        organizationName: value.organizationName,
        name: value.workspaceName,
        slug: value.workspaceSlug,
        description: "",
      });
      const invitations: WorkspaceInvitation[] = value.invites
        .filter((item) => item.email.trim())
        .map((item) => ({
          id: id("invite"),
          email: item.email.trim().toLowerCase(),
          role: item.role,
          status: "pending",
          expiresAt: new Date(Date.now() + 7 * 86400000).toISOString(),
        }));
      commit((previous) => ({
        ...previous,
        onboarding: {
          ...value,
          step: 3,
          completed: true,
          workspaceId: created.id,
        },
        data: {
          ...previous.data,
          [created.id]: { ...previous.data[created.id], invitations },
        },
      }));
    },
    [commit, createWorkspace, currentMember.email, setWorkspace],
  );
  const retryPersistence = useCallback(() => {
    try {
      localStorage.setItem(SAAS_STORAGE_KEY, JSON.stringify(stateRef.current));
      setPersistenceError(null);
    } catch {
      setPersistenceError("write");
    }
  }, []);

  const value = useMemo<WorkspaceContextValue>(
    () => ({
      ready,
      persistenceError,
      workspace,
      workspaces: state.workspaces,
      workspaceId,
      currentMemberId: state.currentMemberId,
      currentMember,
      role,
      previewRole,
      setPreviewRole,
      can,
      setWorkspace,
      createWorkspace,
      updateWorkspace,
      customers: data.customers,
      setCustomers,
      importCustomers,
      members: data.members,
      invitations: data.invitations,
      inviteMember,
      resendInvitation: (targetId) => changeInvitation(targetId, "pending"),
      revokeInvitation: (targetId) => changeInvitation(targetId, "revoked"),
      acceptInvitation,
      changeMemberRole,
      removeMember,
      transferOwnership,
      notes: data.notes,
      addNote,
      files: data.files ?? {},
      attachFiles,
      activity: data.activity,
      recordActivity,
      savedViews: data.savedViews,
      setSavedViews,
      customerView: data.customerView,
      setCustomerView,
      onboarding: state.onboarding,
      setOnboarding,
      completeOnboarding,
      retryPersistence,
    }),
    [
      ready,
      persistenceError,
      workspace,
      state.workspaces,
      state.currentMemberId,
      state.onboarding,
      workspaceId,
      currentMember,
      role,
      previewRole,
      setPreviewRole,
      can,
      setWorkspace,
      createWorkspace,
      updateWorkspace,
      data,
      setCustomers,
      importCustomers,
      inviteMember,
      changeInvitation,
      acceptInvitation,
      changeMemberRole,
      removeMember,
      transferOwnership,
      addNote,
      attachFiles,
      recordActivity,
      setSavedViews,
      setCustomerView,
      setOnboarding,
      completeOnboarding,
      retryPersistence,
    ],
  );
  return <Context.Provider value={value}>{children}</Context.Provider>;
}

/** Frontend context; production services must independently authorize each action. */
export function useWorkspace(): WorkspaceContextValue {
  const value = useContext(Context);
  if (!value) throw new Error("useWorkspace requires WorkspaceProvider.");
  return value;
}

