/** Untrusted browser persistence is checked before it reaches any UI. */
export function parseSaasState(value: unknown): SaasDemoState | null {
  const parsed = stateSchema.safeParse(value);
  if (!parsed.success) return null;
  const state = parsed.data as SaasDemoState;
  const ids = state.workspaces.map((item) => item.id);
  if (
    new Set(ids).size !== ids.length ||
    !ids.includes(state.activeWorkspaceId)
  )
    return null;
  const slugs = state.workspaces.map((item) => item.slug);
  if (new Set(slugs).size !== slugs.length) return null;
  for (const id of ids) {
    if (!Object.hasOwn(state.data, id)) return null;
    const data = state.data[id];
    if (
      data.members.filter((member) => member.role === "owner").length !== 1 ||
      !data.members.some(
        (member) => member.role === "owner" && member.status === "active",
      )
    )
      return null;
    if (
      !data.members.some(
        (member) =>
          member.id === state.currentMemberId && member.status === "active",
      )
    )
      return null;
    if (
      new Set(data.customers.map((item) => item.id)).size !==
      data.customers.length
    )
      return null;
    if (
      new Set(data.members.map((item) => item.id)).size !== data.members.length
    )
      return null;
    if (
      new Set(data.members.map((item) => item.email.toLowerCase())).size !==
      data.members.length
    )
      return null;
  }
  return state;
}

export function updateWorkspaceData(
  state: SaasDemoState,
  id: string,
  updater: (previous: WorkspaceData) => WorkspaceData,
): SaasDemoState {
  if (!Object.hasOwn(state.data, id)) throw new SaasError("missing");
  return { ...state, data: { ...state.data, [id]: updater(state.data[id]) } };
}
export function transferWorkspaceOwnership(
  members: WorkspaceMember[],
  actorId: string,
  targetId: string,
): WorkspaceMember[] {
  const actor = members.find((item) => item.id === actorId);
  const target = members.find((item) => item.id === targetId);
  if (actor?.role !== "owner" || actor.status !== "active")
    throw new SaasError("permission");
  if (!target || target.status !== "active" || actorId === targetId)
    throw new SaasError("invalid");
  return members.map((item) =>
    item.id === actorId
      ? { ...item, role: "admin" }
      : item.id === targetId
        ? { ...item, role: "owner" }
        : item,
  );
}
export function changeWorkspaceMemberRole(
  members: WorkspaceMember[],
  targetId: string,
  role: WorkspaceRole,
  actorId?: string,
): WorkspaceMember[] {
  const target = members.find((item) => item.id === targetId);
  if (!target) throw new SaasError("missing");
  if (target.role === "owner" || role === "owner" || targetId === actorId)
    throw new SaasError("owner");
  return members.map((item) =>
    item.id === targetId ? { ...item, role } : item,
  );
}
export function removeWorkspaceMember(
  members: WorkspaceMember[],
  actorId: string,
  targetId: string,
): WorkspaceMember[] {
  const target = members.find((item) => item.id === targetId);
  if (!target) throw new SaasError("missing");
  if (target.role === "owner" || targetId === actorId)
    throw new SaasError("owner");
  return members.filter((item) => item.id !== targetId);
}

export type CustomerImportResult = {
  created: number;
  updated: number;
  skipped: number;
  failed: number;
};
/** Transactional merge; callers commit the result only after cancellation checks. */
export function mergeImportedCustomers(
  existing: Customer[],
  imported: Customer[],
  mode: "skip" | "update",
): { customers: Customer[]; result: CustomerImportResult } {
  const customers = existing.map((item) => ({ ...item }));
  const indices = new Map(
    customers.map((item, index) => [item.email.trim().toLowerCase(), index]),
  );
  const result: CustomerImportResult = {
    created: 0,
    updated: 0,
    skipped: 0,
    failed: 0,
  };
  for (const candidate of imported) {
    const parsed = customerSchema.safeParse(candidate);
    if (!parsed.success) {
      result.failed++;
      continue;
    }
    const customer = parsed.data;
    const email = customer.email.trim().toLowerCase();
    const index = indices.get(email);
    if (index !== undefined) {
      if (mode === "skip") {
        result.skipped++;
      } else {
        customers[index] = { ...customer, id: customers[index].id };
        result.updated++;
      }
    } else {
      if (customers.some((item) => item.id === customer.id)) {
        result.failed++;
        continue;
      }
      indices.set(email, customers.length);
      customers.push(customer);
      result.created++;
    }
  }
  return { customers, result };
}

import {
  CommerceError,
  commerceInvoiceSchema,
  commerceOrderSchema,
  commerceProductSchema,
  commerceSnapshotSchema,
  newInvoiceSchema,
  newOrderSchema,
  type CommerceAction,
  type CommerceAdapter,
  type CommerceScope,
} from "./commerce";
import { parseCommerceSnapshot } from "./commerce-state";
import { publicPath } from "./public-path";

export const STRIPE_REDIRECT_HOSTS = [
  "checkout.stripe.com",
  "billing.stripe.com",
  "invoice.stripe.com",
] as const;

export function isTrustedStripeRedirect(value: string) {
  try {
    const url = new URL(value);
    return (
      url.protocol === "https:" &&
      !url.username &&
      !url.password &&
      (!url.port || url.port === "443") &&
      STRIPE_REDIRECT_HOSTS.some((host) => url.hostname === host)
    );
  } catch {
    return false;
  }
}

export function parseStripeAction(
  value: unknown,
): Extract<CommerceAction, { mode: "redirect" }> {
  if (
    typeof value !== "object" ||
    value === null ||
    !("mode" in value) ||
    value.mode !== "redirect" ||
    !("url" in value) ||
    typeof value.url !== "string" ||
    !isTrustedStripeRedirect(value.url)
  )
    throw new CommerceError(
      "provider",
      "The backend returned an invalid Stripe redirect.",
    );
  return { mode: "redirect", url: value.url };
}

export type StripeCommerceOptions = {
  /** A same-origin API path. The default follows the demo's build mount point. */
  baseUrl?: string;
  /** Inject your framework's CSRF token; authentication remains on the server. */
  getCsrfToken?: () => string | null | Promise<string | null>;
  /** Useful for consumer-specific transport and deterministic tests. */
  fetcher?: typeof fetch;
};

const statusErrors: Record<number, [CommerceError["code"], string]> = {
  400: ["validation", "Check the submitted fields."],
  401: ["forbidden", "Sign in to your application before continuing."],
  403: ["forbidden", "Your account cannot perform this action."],
  404: ["unavailable", "The requested record is no longer available."],
  409: ["conflict", "The record changed. Reload before trying again."],
  429: ["provider", "Too many requests. Try again shortly."],
};

/**
 * Browser-to-backend transport only. This module never receives a Stripe key,
 * card details, client-supplied payment totals or a client-side customer id.
 */
export function createStripeCommerceAdapter(
  options: StripeCommerceOptions = {},
): CommerceAdapter {
  const baseUrl = (options.baseUrl ?? publicPath("/api/commerce")).replace(
    /\/+$/,
    "",
  );
  if (
    !baseUrl.startsWith("/") ||
    baseUrl.startsWith("//") ||
    /[\\?#]/.test(baseUrl) ||
    baseUrl.includes("..") ||
    /%2e|%2f|%5c/i.test(baseUrl)
  )
    throw new CommerceError(
      "validation",
      "Use a same-origin commerce API path.",
    );
  const fetcher =
    options.fetcher ?? ((...args: Parameters<typeof fetch>) => fetch(...args));
  async function request(path: string, scope: CommerceScope, body?: unknown) {
    const csrf = body === undefined ? null : await options.getCsrfToken?.();
    if (scope.signal?.aborted)
      throw new CommerceError("conflict", "The request was cancelled.");
    let response: Response;
    try {
      response = await fetcher(`${baseUrl}${path}`, {
        method: body === undefined ? "GET" : "POST",
        credentials: "same-origin",
        mode: "same-origin",
        redirect: "error",
        cache: "no-store",
        signal: scope.signal,
        headers: {
          Accept: "application/json",
          "X-Aureform-Request": "commerce",
          ...(body === undefined ? {} : { "Content-Type": "application/json" }),
          ...(csrf ? { "X-CSRF-Token": csrf } : {}),
        },
        ...(body === undefined ? {} : { body: JSON.stringify(body) }),
      });
    } catch {
      throw new CommerceError(
        scope.signal?.aborted ? "conflict" : "provider",
        scope.signal?.aborted
          ? "The request was cancelled."
          : "The commerce backend is unavailable. Try again.",
      );
    }
    if (!response.ok) {
      const [code, message] = statusErrors[response.status] ?? [
        "provider",
        "The commerce backend could not complete the request.",
      ];
      throw new CommerceError(code, message);
    }
    if (!response.headers.get("content-type")?.includes("application/json")) {
      throw new CommerceError(
        "provider",
        "The commerce backend must return JSON.",
      );
    }
    try {
      return (await response.json()) as unknown;
    } catch {
      throw new CommerceError(
        "provider",
        "The commerce backend returned invalid JSON.",
      );
    }
  }
  const scopeBody = (scope: CommerceScope) => ({
    workspaceId: scope.workspaceId,
  });
  const invalid = () =>
    new CommerceError(
      "provider",
      "The commerce backend returned an invalid record.",
    );
  return {
    mode: "stripe",
    async load(scope) {
      const query = new URLSearchParams({ workspaceId: scope.workspaceId });
      const response = await request(`?${query}`, scope);
      // Check both the shape and relationships, including purchase-time totals.
      const snapshot = parseCommerceSnapshot(response);
      if (!snapshot || !commerceSnapshotSchema.safeParse(response).success)
        throw invalid();
      return snapshot;
    },
    async saveProduct(product, scope) {
      const input = commerceProductSchema.safeParse(product);
      if (!input.success)
        throw new CommerceError("validation", "Check the product fields.");
      const result = commerceProductSchema.safeParse(
        await request("/products/save", scope, {
          ...scopeBody(scope),
          product: input.data,
        }),
      );
      if (!result.success || result.data.id !== product.id) throw invalid();
      return result.data;
    },
    async archiveProduct(productId, scope) {
      const result = commerceProductSchema.safeParse(
        await request("/products/archive", scope, {
          ...scopeBody(scope),
          productId,
        }),
      );
      if (!result.success || result.data.id !== productId) throw invalid();
      return result.data;
    },
    async syncProduct(productId, scope) {
      const result = commerceProductSchema.safeParse(
        await request("/products/sync", scope, {
          ...scopeBody(scope),
          productId,
        }),
      );
      if (!result.success || result.data.id !== productId) throw invalid();
      return result.data;
    },
    async createOrder(input, scope) {
      const validated = newOrderSchema.safeParse(input);
      if (!validated.success)
        throw new CommerceError("validation", "Check the order fields.");
      const result = commerceOrderSchema.safeParse(
        await request("/orders/create", scope, {
          ...scopeBody(scope),
          input: validated.data,
        }),
      );
      if (!result.success) throw invalid();
      return result.data;
    },
    async updateOrderStatus(orderId, status, scope) {
      const result = commerceOrderSchema.safeParse(
        await request("/orders/status", scope, {
          ...scopeBody(scope),
          orderId,
          status,
        }),
      );
      if (!result.success || result.data.id !== orderId) throw invalid();
      return result.data;
    },
    async createInvoice(input, scope) {
      const validated = newInvoiceSchema.safeParse(input);
      if (!validated.success)
        throw new CommerceError("validation", "Check the invoice fields.");
      const result = commerceInvoiceSchema.safeParse(
        await request("/invoices/create", scope, {
          ...scopeBody(scope),
          input: validated.data,
        }),
      );
      if (!result.success) throw invalid();
      return result.data;
    },
    async checkout(input, scope) {
      if (
        !["order", "invoice", "subscription"].includes(input.kind) ||
        !input.id ||
        input.id.length > 100
      )
        throw new CommerceError(
          "validation",
          "Choose an available checkout record.",
        );
      return parseStripeAction(
        await request("/checkout", scope, {
          ...scopeBody(scope),
          ...input,
        }),
      );
    },
    async portal(scope) {
      return parseStripeAction(
        await request("/portal", scope, scopeBody(scope)),
      );
    },
  };
}

import { clsx, type ClassValue } from "clsx";
import { twMerge } from "tailwind-merge";
export function cn(...inputs: ClassValue[]) {
  return twMerge(clsx(inputs));
}
export function downloadText(
  filename: string,
  text: string,
  type = "text/plain",
) {
  const url = URL.createObjectURL(new Blob([text], { type }));
  const a = document.createElement("a");
  a.href = url;
  a.download = filename;
  a.click();
  setTimeout(() => URL.revokeObjectURL(url), 1000);
}
export function csv(rows: Record<string, unknown>[]) {
  if (!rows.length) return "";
  const keys = Object.keys(rows[0]);
  const escape = (value: unknown) => {
    const raw = String(value ?? "");
    const safe = /^[=+@\t\r-]/.test(raw) ? `'${raw}` : raw;
    return `"${safe.replaceAll('"', '""')}"`;
  };
  return [
    keys.map(escape).join(","),
    ...rows.map((row) => keys.map((k) => escape(row[k])).join(",")),
  ].join("\r\n");
}

